<div class="relative" x-data="{ open: false }"> <button @click="open = !open" class="flex items-center gap-2 px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50"> @php $current = $campuses->firstWhere('id', $currentCampusId); @endphp <span>{{ $current->name ?? 'Select Campus' }}</span> <svg class="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7" /></svg> </button> <div x-show="open" @click.outside="open = false" x-cloak class="absolute z-10 mt-1 w-56 bg-white border border-gray-200 rounded-md shadow-lg"> @forelse($campuses as $campus) <button wire:click="switchTo({{ $campus->id }})" @click="open = false" class="block w-full text-left px-4 py-2 text-sm hover:bg-gray-100 {{ $campus->id === $currentCampusId ? 'font-semibold text-indigo-600' : 'text-gray-700' }}"> {{ $campus->name }} </button> @empty <div class="px-4 py-2 text-sm text-gray-500">No campuses yet</div> @endforelse </div> </div>